use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn read_entries(dir: &mut fs::ReadDir) -> Result<HashMap<String, fs::Metadata>, std::io::Error> {
    let mut entries_map = HashMap::new();

    for entry in dir {
        let entry = entry?;
        let path = entry.path();
        let file_name = path.file_name().and_then(|s| s.to_str()).map(String::from);

        if let Some(file_name) = file_name {
            if let Ok(metadata) = fs::metadata(&path) {
                entries_map.insert(file_name, metadata);
            }
        }
    }

    Ok(entries_map)
}

fn main() {
    let mut dir = fs::read_dir("path_to_directory").expect("read directory");
    let entries = read_entries(&mut dir).expect("read entries");

    // Example usage
    println!("{:?}", entries);
}
```

In the solution, the `read_entries` function takes a mutable reference to a directory and iterates through its entries. For each file entry, it retrieves the file name and metadata, then populates a `HashMap` with the file name as the key and the metadata as the value. Any potential errors during the process are handled and returned as a `Result`. The `main` function demonstrates the usage of the `read_entries` function by reading the contents of a directory and printing the resulting mapping of file names to metadata."}]

