use crossterm::style::{Color, Print, ResetColor, SetForegroundColor};
use lazy_static::lazy_static;
use minimad::mad_inline;
use std::collections::HashMap;
use std::fs;

lazy_static! {
    static ref COLORS: Vec<Color> = vec![Color::Red, Color::Green, Color::Blue];
}

fn main() {
    // Read the contents of the input file
    let contents = fs::read_to_string("input.txt").expect("Unable to read file");

    // Process the text and count word occurrences
    let mut word_count: HashMap<String, u32> = HashMap::new();
    for word in contents.split_whitespace() {
        let cleaned_word = word.trim_matches(|c: char| !c.is_alphabetic()).to_lowercase();
        *word_count.entry(cleaned_word.to_string()).or_insert(0) += 1;
    }

    // Sort the word count in descending order
    let mut sorted_word_count: Vec<(&String, &u32)> = word_count.iter().collect();
    sorted_word_count.sort_by(|a, b| b.1.cmp(a.1));

    // Display the word count in a tabular format
    for (i, (word, count)) in sorted_word_count.iter().enumerate() {
        let color = if i < 3 { &COLORS[i] } else { &Color::Reset };
        print!(
            "{}{:>2}. {:<15} {:>3}{}\n",
            SetForegroundColor(color),
            i + 1,
            word,
            count,
            ResetColor
        );
    }
}
