fn interpret_input(recipe: &Recipe, assignments: &HashMap<String, f64>, text: &str) -> Result<f64, CompilationError> {
    let mut interpreted_text = String::new();
    let mut index = 0;

    while index < text.len() {
        if text[index..].starts_with("{{") {
            let end_index = text[index..].find("}}").map(|i| index + i + 2).unwrap_or(text.len());
            let variable_name = &text[index + 2..end_index - 2].trim();

            if let Some(value) = assignments.get(variable_name) {
                interpreted_text.push_str(&value.to_string());
            } else if recipe.parameters.iter().any(|p| p.name == variable_name) {
                interpreted_text.push_str(variable_name);
            } else {
                return Err(CompilationError {
                    index,
                    // Other error properties
                });
            }

            index = end_index;
        } else {
            interpreted_text.push(text.chars().nth(index).unwrap());
            index += 1;
        }
    }

    // Evaluate the interpreted text as an expression and return the result
    // For simplicity, let's assume the interpreted text is a valid arithmetic expression
    let result = interpreted_text.parse::<f64>().map_err(|_| CompilationError {
        index: 0,  // Set the index to 0 for simplicity
        // Other error properties
    })?;

    Ok(result)
}
```

