impl FileSystem {
    fn read_file(&self, ino: u64) -> Result<Vec<u8>, Error> {
        let mut file_reader = BufReader::new(&self.device).by_ref();
        let superblock = &self.sb;
        let root_ino = if ino == FUSE_ROOT_ID {
            self.sb.sb_rootino
        } else {
            ino
        };

        let mut file_data = Vec::new();
        let mut buffer = [0; 4096];  // Assuming a buffer size of 4096 bytes

        // Seek to the position of the file data based on the inode number
        file_reader.seek(SeekFrom::Start(superblock.get_inode_offset(root_ino)))?;

        loop {
            let bytes_read = file_reader.read(&mut buffer)?;
            if bytes_read == 0 {
                break;  // End of file
            }
            file_data.extend_from_slice(&buffer[..bytes_read]);
        }

        Ok(file_data)
    }
}
```

