    fn receive_incoming_message(&self) -> Promise<(), Error> {
        let mut connection = self.connection.borrow_mut();
        match *connection {
            Err(ref e) => Promise::err(e.clone()),
            Ok(ref mut conn) => conn.receive_incoming_message(),
        }
