    fn ok(value: T) -> Self {
        Promise::Ok(value)
    }

    fn err(error: E) -> Self {
        Promise::Err(error)
    }
}

// Implement the message_loop function
fn message_loop<VatId>(weak_state: Weak<ConnectionState<VatId>>) -> Promise<(), Error> {
    let state = match weak_state.upgrade() {
        None => return Promise::err(Error::disconnected("message loop cannot continue without a connection".into())),
        Some(c) => c,
