    message: &'i str,
}

fn parse_number(input: &str) -> IResult<&str, NumberOrPercentage> {
    map_res(
        nom::character::complete::double,
        |num| Ok(NumberOrPercentage::Number(num)),
    )(input)
}

fn parse_percentage(input: &str) -> IResult<&str, NumberOrPercentage> {
    map_res(
        preceded(char('%'), nom::character::complete::double),
        |num| Ok(NumberOrPercentage::Percentage(num)),
    )(input)
}

fn parse_markup(input: &str) -> Result<NumberOrPercentage, ParseError> {
    let (_, result) = parse_number(input)
        .or_else(|_err| parse_percentage(input))
        .map_err(|_err| ParseError { message: "Failed to parse input" })?;

    Ok(result)
}

fn main() {
