    fn new(name: String, value: i32) -> Covenant {
        Covenant { name, value }
    }

    fn serialize_hex(&self) -> String {
        let name_hex = self.name.as_bytes().iter().map(|b| format!("{:02X}", b)).collect::<Vec<String>>().join("");
        let value_hex = format!("{:X}", self.value);
        format!("{}{}", name_hex, value_hex)
    }

    fn deserialize_hex(hex_string: &str) -> Result<Covenant, &'static str> {
        if hex_string.len() % 2 != 0 {
            return Err("Invalid hexadecimal string length");
        }

        let bytes: Vec<u8> = (0..hex_string.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hex_string[i..i + 2], 16).unwrap())
            .collect();

        let name = match str::from_utf8(&bytes[0..bytes.len() - 1]) {
            Ok(s) => s.to_string(),
            Err(_) => return Err("Invalid UTF-8 sequence"),
        };

        let value = i32::from_str_radix(&hex_string[hex_string.len() - 1..], 16).unwrap();

        Ok(Covenant { name, value })
    }
}

fn main() {
    let covenant = Covenant::new("SampleCovenant".to_string(), 123);
    let serialized = covenant.serialize_hex();
    println!("Serialized: {}", serialized);

    let deserialized = Covenant::deserialize_hex(&serialized).unwrap();
    println!("Deserialized: {:?}", deserialized);
}
