struct FileManager {
    folders: Vec<Folder>,
}

impl FolderService for FileManager {
    fn update(&self, request: UpdateRequest) -> Result<Folder, ServiceError> {
        if let Some(folder) = self.folders.iter_mut().find(|f| f.id == request.id) {
            folder.name = request.new_name.clone();
            Ok(folder.clone())
        } else {
            Err(ServiceError::NotFound)
        }
    }

    fn delete(&self, id: i32) -> Result<Folder, ServiceError> {
        if let Some(index) = self.folders.iter().position(|f| f.id == id) {
            Ok(self.folders.remove(index))
        } else {
            Err(ServiceError::NotFound)
        }
    }
}
```

