    let fast_threshold = params.fast_threshold;

    for y in patch_size..image.len() - patch_size {
        for x in patch_size..image[0].len() - patch_size {
            let center_pixel = image[y][x];
            let is_feature = is_feature_point(&image, x, y, patch_size, fast_threshold, center_pixel);
            if is_feature {
                features.push((x as i32, y as i32));
            }
        }
    }

    features
}

fn is_feature_point(image: &Vec<Vec<i32>>, x: usize, y: usize, patch_size: usize, fast_threshold: i32, center_pixel: i32) -> bool {
    let offsets = [
        (0, -patch_size as i32), (-patch_size as i32, 0), (0, patch_size as i32), (patch_size as i32, 0),
        (patch_size as i32, patch_size as i32), (-patch_size as i32, patch_size as i32), (-patch_size as i32, -patch_size as i32), (patch_size as i32, -patch_size as i32),
    ];

    let mut brighter_count = 0;
    let mut darker_count = 0;

    for &(dx, dy) in &offsets {
        let neighbor_pixel = image[(y as i32 + dy) as usize][(x as i32 + dx) as usize];
        if neighbor_pixel - center_pixel >= fast_threshold {
            brighter_count += 1;
        } else if center_pixel - neighbor_pixel >= fast_threshold {
            darker_count += 1;
        }
    }

    brighter_count >= 3 || darker_count >= 3
}
