fn even_fibonacci_sum(limit: u32) -> u32 {
    let (mut a, mut b) = (1, 2);
    let mut sum = 0;

    while b <= limit {
        if b % 2 == 0 {
            sum += b;
        }
        let next = a + b;
        a = b;
        b = next;
    }

    sum
}

fn main() {
    assert_eq!(even_fibonacci_sum(10), 10);
    assert_eq!(even_fibonacci_sum(100), 44);
    assert_eq!(even_fibonacci_sum(4000000), 4613732);
}
