fn parse_duration(input: &str) -> Result<u64, String> {
    let mut total_seconds = 0;
    let mut current_value = 0;
    let mut current_unit = "s"; // Default unit is seconds

    for c in input.chars() {
        if c.is_digit(10) {
            current_value = current_value * 10 + c.to_digit(10).unwrap() as u64;
        } else if c.is_alphabetic() {
            match c {
                'h' => {
                    total_seconds += current_value * 3600;
                    current_value = 0;
                    current_unit = "h";
                }
                'm' => {
                    total_seconds += current_value * 60;
                    current_value = 0;
                    current_unit = "m";
                }
                's' => {
                    total_seconds += current_value;
                    current_value = 0;
                    current_unit = "s";
                }
                _ => return Err(format!("Invalid unit: {}", c)),
            }
        } else if c.is_whitespace() {
            // Ignore whitespace
        } else {
            return Err(format!("Invalid character: {}", c));
        }
    }

    match current_unit {
        "h" => total_seconds += current_value * 3600,
        "m" => total_seconds += current_value * 60,
        "s" => total_seconds += current_value,
        _ => return Err(format!("Invalid unit: {}", current_unit)),
    }

    Ok(total_seconds)
}

fn main() {
    // Test cases
    println!("{}", parse_duration("1h 30m 15s").unwrap()); // Output: 5415
    println!("{}", parse_duration("2h 45s").unwrap()); // Output: 7205
    println!("{}", parse_duration("10m").unwrap()); // Output: 600
    println!("{}", parse_duration("3 days").unwrap()); // Output: 259200
}
```
