    let parts: Vec<&str> = input.split("||").map(|s| s.trim()).collect();

    if parts.len() == 1 {
        Some(Expression::Value(parts[0].to_string()))
    } else if parts.len() == 2 {
        let left = Expression::Value(parts[0].to_string());
        let right = Expression::Value(parts[1].to_string());
        Some(Expression::Or(Box::new(left), Box::new(right)))
    } else {
        None
    }
}

fn main() {
    let input = "type=image || bing";
    if let Some(expr) = parse_expression(input) {
        println!("{:?}", expr);
    } else {
        println!("Invalid expression");
    }
}
```

The `parse_expression` function splits the input string based on the logical OR operator `||` and constructs the expression tree accordingly. If the input contains only one value, it returns a `Value` expression. If the input contains two values separated by `||`, it constructs an `Or` expression with the left and right sub-expressions. If the input contains an invalid number of parts, it returns `None`."}]

