use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;
use std::mem::MaybeUninit as MU;

struct CircularBuffer<T, const N: usize> {
    data: [MU<T>; N],
    idx: AtomicUsize,
}

impl<T: Default + Copy, const N: usize> CircularBuffer<T, N> {
    fn new() -> Self {
        let data = unsafe { MU::uninit().assume_init() };
        CircularBuffer {
            data,
            idx: AtomicUsize::new(0),
        }
    }

    fn push(&self, value: T) {
        let current_idx = self.idx.fetch_add(1, Ordering::Relaxed) % N;
        unsafe {
            std::ptr::write(self.data[current_idx].as_mut_ptr(), value);
        }
    }

    fn pop(&self) -> Option<T> {
        let current_idx = (self.idx.load(Ordering::Relaxed) + N - 1) % N;
        if self.is_empty() {
            None
        } else {
            let value = unsafe { std::ptr::read(self.data[current_idx].as_ptr()) };
            Some(value)
        }
    }

    fn is_empty(&self) -> bool {
        self.idx.load(Ordering::Relaxed) == 0
    }

    fn is_full(&self) -> bool {
        self.idx.load(Ordering::Relaxed) == N
    }
}

fn main() {
    let buffer: CircularBuffer<i32, 5> = CircularBuffer::new();
    buffer.push(10);
    buffer.push(20);
    println!("{:?}", buffer.pop()); // Output: Some(10)
    println!("{:?}", buffer.pop()); // Output: Some(20)
    println!("{:?}", buffer.pop()); // Output: None
}
```

In this solution, we define a `CircularBuffer` struct that holds the data array and the index. We implement methods for `push`, `pop`, `is_empty`, and `is_full` operations. The `AtomicUsize` type is used for the index to ensure thread safety, and the `Mutex` type is not needed as the operations are lock-free. The `unsafe` blocks are used to perform low-level pointer operations for efficient buffer manipulation. The `main` function demonstrates the usage of the circular buffer."}]

