    fn calculate(&self) -> f64 {
        let mut circle_points = 0;
        let total_points = 1000000; // Number of random points to generate

        let mut rng = rand::thread_rng();

        for _ in 0..total_points {
            let x = rng.gen::<f64>();
            let y = rng.gen::<f64>();

            // Check if the point is inside the unit circle
            if (x - 0.5).powi(2) + (y - 0.5).powi(2) <= 0.25 {
                circle_points += 1;
            }
        }

        // Calculate the ratio of points inside the circle to the total points
        let ratio = circle_points as f64 / total_points as f64;

        // Use the ratio to estimate the value of π
        let estimated_pi = ratio * 4.0;

        estimated_pi
    }
}

