#[derive(Debug)]
pub struct CustomLock {
    mutex: Mutex<()>,
    rw_lock: RwLock<()>,
    exclusive_count: AtomicUsize,
}

impl CustomLock {
    pub fn new() -> Self {
        CustomLock {
            mutex: Mutex::new(()),
            rw_lock: RwLock::new(()),
            exclusive_count: AtomicUsize::new(0),
        }
    }

    pub fn lock(&self) -> Result<CustomLockGuard, MutexLockError> {
        self.mutex.lock().map(|guard| {
            self.exclusive_count.fetch_add(1, Ordering::SeqCst);
            CustomLockGuard::Exclusive(guard)
        }).map_err(|_| MutexLockError::Poisoned)
    }

    pub fn try_lock(&self) -> Result<CustomLockGuard, OptionLockError> {
        match self.mutex.try_lock() {
            Ok(guard) => {
                self.exclusive_count.fetch_add(1, Ordering::SeqCst);
                Ok(CustomLockGuard::Exclusive(guard))
            }
            Err(_) => Err(OptionLockError::Contended),
        }
    }

    pub fn lock_shared(&self) -> Result<CustomLockGuard, MutexLockError> {
        self.rw_lock.read().map(|guard| CustomLockGuard::Shared(guard)).map_err(|_| MutexLockError::Poisoned)
    }

    pub fn try_lock_shared(&self) -> Result<CustomLockGuard, OptionLockError> {
        match self.rw_lock.try_read() {
            Ok(guard) => Ok(CustomLockGuard::Shared(guard)),
            Err(_) => Err(OptionLockError::Contended),
        }
    }
}

#[derive(Debug)]
pub enum CustomLockGuard {
    Exclusive(MutexGuard<'static, ()>),
    Shared(RwLockReadGuard<'static, ()>),
}

impl CustomLockGuard {
    pub fn unlock(&self) {
        match self {
            CustomLockGuard::Exclusive(guard) => {
                guard.unlock();
            }
            CustomLockGuard::Shared(guard) => {
                guard.unlock();
            }
        }
    }
}

#[derive(Debug)]
pub enum MutexLockError {
    Poisoned,
}

#[derive(Debug)]
pub enum OptionLockError {
    Contended,
}
