fn mandelbrot_visualization(bounds: (Complex<f64>, Complex<f64>), width: usize, height: usize, max_iterations: u32) -> Vec<Vec<u8>> {
    let mut image = vec![vec![0; width]; height];

    for (i, row) in image.iter_mut().enumerate() {
        for (j, pixel) in row.iter_mut().enumerate() {
            let x = bounds.0.re + (bounds.1.re - bounds.0.re) * j as f64 / width as f64;
            let y = bounds.0.im + (bounds.1.im - bounds.0.im) * i as f64 / height as f64;
            let c = Complex::new(x, y);
            let mut z = Complex::new(0., 0.);
            let mut iterations = 0;

            while z.norm() <= 2. && iterations < max_iterations {
                z = z * z + c;
                iterations += 1;
            }

            *pixel = if iterations < max_iterations {
                255 - iterations as u8;
            } else {
                0;
            }
        }
    }

    image
}

