fn resolve_dependencies(code: &str) -> Vec<String> {
    let mut dependencies = Vec::new();
    let lines: Vec<&str> = code.lines().collect();

    for line in lines {
        if let Some(module) = line.strip_prefix("mod ") {
            let module_name = module.trim_end_matches(';');
            dependencies.push(module_name.to_string());
        } else if let Some(pub_use) = line.strip_prefix("pub use ") {
            let module_name = pub_use.split("::").last().unwrap().trim_end_matches(';');
            dependencies.push(module_name.to_string());
        }
    }

    dependencies
}
