#[derive(Debug)]
struct GlobMatcher {
    pattern: Pattern,
}

impl GlobMatcher {
    fn from_str(s: &str) -> Result<Self, Box<dyn Error>> {
        let trimmed = s.trim();
        let pattern = Pattern::new(trimmed)?;
        Ok(GlobMatcher { pattern })
    }

    fn matches(&self, s: &str) -> bool {
        self.pattern.matches(s)
    }
}

#[derive(Debug)]
struct GlobMatchers {
    inner: Vec<GlobMatcher>,
}

impl GlobMatchers {
    fn from_str(s: &str) -> Result<Self, Box<dyn Error>> {
        let splits: Vec<&str> = s.split(',').map(|s| s.trim()).collect();
        let mut inner = Vec::new();
        for split in splits {
            inner.push(GlobMatcher::from_str(split)?);
        }
        Ok(GlobMatchers { inner })
    }

    fn matches(&self, s: &str) -> bool {
        self.inner.iter().any(|matcher| matcher.matches(s))
    }
}

impl std::ops::Deref for GlobMatchers {
    type Target = [GlobMatcher];

    fn deref(&self) -> &Self::Target {
        &self.inner
    }
}

fn main() {
    let patterns = "abc*,def?";
    let matchers = GlobMatchers::from_str(patterns).unwrap();
    let test_strings = ["abcd", "defg", "xyz"];
    for string in &test_strings {
        println!("String: {}, Matches: {}", string, matchers.matches(string));
    }
}
```

