fn print_tree(items: Vec<&str>) {
    let mut stack: Vec<(usize, &str)> = Vec::new();
    for item in items {
        let level = item.chars().take_while(|&c| c == ' ').count();
        while let Some((top_level, _)) = stack.last() {
            if level <= *top_level {
                stack.pop();
            } else {
                break;
            }
        }
        if let Some((_, parent)) = stack.last() {
            println!("{}- {}", "  ".repeat(stack.len()), item.trim());
        } else {
            println!("- {}", item.trim());
        }
        stack.push((level, item));
    }
}

fn main() {
    let input = vec![
        "Fruits",
        "  Apple",
        "  Banana",
        "    Red Banana",
        "    Yellow Banana",
        "  Orange",
        "Vegetables",
        "  Carrot",
        "  Tomato",
    ];
    print_tree(input);
}
```

