    fn is_valid_utf8(&self) -> bool {
        let mut bytes = self.as_bytes().iter().peekable();

        while let Some(&b) = bytes.next() {
            let num_bytes = match b {
                0..=127 => continue,
                192..=223 => 2,
                224..=239 => 3,
                240..=247 => 4,
                _ => return false,
            };

            for _ in 0..num_bytes-1 {
