pub fn compress(input: &str) -> Vec<u16> {
    let mut dictionary = decoder::create_dictionary();
    let mut result = Vec::new();
    let mut w = String::new();

    for c in input.chars() {
        let wc = format!("{}{}", w, c);
        if dictionary.contains(&wc) {
            w = wc;
        } else {
            result.push(dictionary.get_code(&w));
            dictionary.add_entry(wc.clone());
            w = c.to_string();
        }
    }

    if !w.is_empty() {
        result.push(dictionary.get_code(&w));
    }

    result
}

pub fn decompress(compressed: &[u16]) -> String {
    let mut dictionary = decoder::create_dictionary();
    let mut result = String::new();
    let mut entry = String::new();
    let mut w = String::new();

    for &k in compressed {
        let entry = if let Some(e) = dictionary.get_entry(k) {
            e
        } else {
            let e = format!("{}{}", w, &w[..1]);
            dictionary.add_entry(e.clone());
