use std::sync::{Arc, Condvar, Mutex};

struct SignalGuard {
    condvar: Condvar,
    mutex: Mutex<bool>,
}

impl SignalGuard {
    fn new() -> Self {
        SignalGuard {
            condvar: Condvar::new(),
            mutex: Mutex::new(false),
        }
    }

    fn wait(&self) {
        let mut guard = self.mutex.lock().unwrap();
        while !*guard {
            guard = self.condvar.wait(guard).unwrap();
        }
    }

    fn signal(&self) {
        let mut guard = self.mutex.lock().unwrap();
        *guard = true;
        self.condvar.notify_one();
    }
}

struct StopGuard {
    stop: Arc<SignalGuard>,
}

impl StopGuard {
    fn new(stop: Arc<SignalGuard>) -> Self {
        StopGuard { stop }
    }

    fn wake(&self) {
        self.stop.signal();
    }
}

