pub struct Stack {
    data: [i32; 10],
    top: usize,
}

impl Stack {
    pub fn new() -> Stack {
        Stack { data: [0; 10], top: 0 }
    }

    pub fn push(&mut self, value: i32) {
        if self.top < 10 {
            self.data[self.top] = value;
            self.top += 1;
        }
    }

    pub fn pop(&mut self) -> Option<i32> {
        if self.top > 0 {
            self.top -= 1;
            Some(self.data[self.top])
        } else {
            None
        }
    }

    pub fn peek(&self) -> Option<i32> {
        if self.top > 0 {
            Some(self.data[self.top - 1])
        } else {
            None
        }
    }

    pub fn is_empty(&self) -> bool {
        self.top == 0
    }
}

pub fn is_balanced(input: &str) -> bool {
    let mut stack = Stack::new();
    for c in input.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c as i32),
            ')' => {
                if stack.pop() != Some('(' as i32) {
                    return false;
                }
            }
            ']' => {
                if stack.pop() != Some('[' as i32) {
                    return false;
                }
            }
            '}' => {
                if stack.pop() != Some('{' as i32) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}
