#[derive(Debug)]
enum ByteUnit {
    KiB,
    MiB,
    GiB,
    TiB,
    PiB,
}

impl ByteUnit {
    fn to_bytes(&self) -> i64 {
        match self {
            ByteUnit::KiB => 1024,
            ByteUnit::MiB => 1024 * 1024,
            ByteUnit::GiB => 1024 * 1024 * 1024,
            ByteUnit::TiB => 1024 * 1024 * 1024 * 1024,
            ByteUnit::PiB => 1024 * 1024 * 1024 * 1024 * 1024,
        }
    }
}

fn convert_to_bytes(size: &str) -> Result<i64, String> {
    let size = size.trim();
    let has_unit = size.chars().any(|c| c.is_alphabetic());

    let (value_str, unit_str) = if has_unit {
        size.split_at(size.chars().position(|c| c.is_alphabetic()).unwrap())
    } else {
        (size, "MiB")
    };

    let value = match value_str.parse::<i64>() {
        Ok(v) => v,
        Err(_) => return Err("Invalid size value".to_string()),
    };

    let unit = match unit_str.to_lowercase().as_str() {
        "kib" => ByteUnit::KiB,
        "mib" => ByteUnit::MiB,
        "gib" => ByteUnit::GiB,
        "tib" => ByteUnit::TiB,
        "pib" => ByteUnit::PiB,
        _ => return Err("Invalid unit".to_string()),
    };

    Ok(value * unit.to_bytes())
}

fn main() {
    // Test cases
    println!("{:?}", convert_to_bytes("100 MiB"));  // Output: Ok(104857600)
    println!("{:?}", convert_to_bytes("50 GiB"));   // Output: Ok(53687091200)
