    let e = hash_concat(&r, m);
    let s = (k - x * e) % (p - BigUint::one());
    (r, s)
}

fn hash_concat(r: &BigUint, m: &str) -> BigUint {
    let mut hasher = Sha256::new();
    hasher.update(r.to_bytes_be());
    hasher.update(m.as_bytes());
    BigUint::from_bytes_be(&hasher.finalize())
}

fn main() {
