    let sequence_string = auto_types
        .iter()
        .filter_map(|at| at.sequence.as_ref())
        .filter(|&seq| !seq.is_empty())
        .map(|seq| seq.to_string())
        .collect::<Vec<String>>()
        .join(",");

    let mut unique_associations: HashSet<&AutoTypeAssociation> = HashSet::new();
