fn let_user_choose_example(examples: Vec<Option<String>>) -> Result<String, Box<dyn std::error::Error>> {
    println!("Choose an example:");

    for (i, optional_example) in examples.iter().enumerate() {
        if let Some(example) = optional_example {
            println!("{}) {}", i + 1, example);
        }
    }
    println!("q) Quit");

    loop {
        let mut input = String::new();
        io::stdin().read_line(&mut input)?;

        let trimmed_input = input.trim();
        if trimmed_input == "q" {
            return Err("User chose to quit".into());
        }

        if let Ok(index) = trimmed_input.parse::<usize>() {
            if index > 0 && index <= examples.len() {
                if let Some(example) = &examples[index - 1] {
                    return Ok(example.clone());
                }
            }
        }

        println!("Invalid input. Please choose a valid example or 'q' to quit:");
    }
}

