#[macro_export]
#[doc(hidden)]
macro_rules! define_error_with_tracer {
    ( $tracer:ty;
      $derive:tt $name:ident;
      {
        $(
          $suberror:ident
          $( { $( $arg_name:ident : $arg_type:ty ),* $(,)? } )?
          $( [ $source:ty ] )?
          | $formatter_arg:pat | $formatter:expr
        ),* $(,)?
      }
    ) => {
        use flex_error::{define_error, TraceError, TraceResult};

        define_error! {
            $derive $name {
                $(
                    $suberror {
                        $( $( $arg_name : $arg_type ),* )?
                        $( [ $source ] )?
                    }
                ),*
            }
        }

        $(
            impl From<$suberror> for $name {
                fn from(err: $suberror) -> Self {
                    $name::from_source(err, <$suberror as TraceError>::source(&err))
                }
            }
        )*

        $(
            impl $suberror {
                fn new( $( $( $arg_name : $arg_type ),* )? ) -> Self {
                    $suberror {
                        $( $( $arg_name ),* )?
                        source: None
                    }
                }
            }

            impl TraceError for $suberror {
                type Tracer = $tracer;

                fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
                    self.source.as_ref().map(|s| s as &dyn std::error::Error)
                }
            }

            impl std::fmt::Display for $suberror {
                fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                    let $formatter_arg = self;
                    write!(f, "{}", $formatter)
                }
            }
        )*
    };
}
```
