use criterion::{criterion_group, criterion_main, Criterion};

fn calculate_average_time(functions: Vec<fn()>) -> String {
    let mut result = String::new();
    let mut group = criterion_group::criterion_group("benchmark_group");

    for (index, function) in functions.iter().enumerate() {
        group.bench_function(format!("Function {}", index), |b| b.iter(|| function()));
    }

    criterion_main!(group);

    for (index, function) in functions.iter().enumerate() {
        let average_time = criterion::black_box(criterion::black_box(group.bench_times()[index].ns_per_iter) / 1_000_000);
        result.push_str(&format!("Average time taken by function_{}: {} ms\n", index, average_time));
    }

    result
}
```

In the solution, the `calculate_average_time` function creates a `criterion_group` and adds each function from the input vector as a benchmark function. It then executes the benchmarks using `criterion_main!` macro. After execution, it retrieves the average time taken by each function and formats the results into a string as per the specified format."}]

