fn is_identical(p: Option<Box<TreeNode>>, q: Option<Box<TreeNode>>) -> bool {
    match (p, q) {
        (None, None) => true,
        (Some(p_node), Some(q_node)) => {
            p_node.val == q_node.val
                && is_identical(p_node.left, q_node.left)
                && is_identical(p_node.right, q_node.right)
        }
        _ => false,
    }
}
