        Cache {
            bits: 0,
            cache_lines: [None; 8],
            lru_counter: 0,
        }
    }

    pub fn access(&mut self, address: u64) {
        let block_index = (address / 8) as usize % 8;
        if let Some(value) = self.cache_lines[block_index] {
            if (value as u64 * 8) != (address & !7) {
                self.cache_lines[block_index] = Some((address & !7) as u32 / 8);
            }
        } else {
            self.cache_lines[block_index] = Some((address & !7) as u32 / 8);
        }
        self.lru_counter += 1;
    }

    pub fn misses(&self) -> u32 {
        let mut miss_count = 0;
        for &line in &self.cache_lines {
            if let Some(value) = line {
                if value * 8 != self.bits & !7 {
                    miss_count += 1;
                }
            } else {
                miss_count += 1;
            }
        }
        miss_count
    }
}
