fn convert_to_datetime(dto: Dto) -> DateTime<FixedOffset> {
    let date = NaiveDate::from_ordinal(1, dto.datetime2.date.days() as i32);
    let ns = dto.datetime2.time.increments as i64 * 10i64.pow(9 - dto.datetime2.time.scale as u32);
    let time = NaiveTime::from_hms(0, 0, 0) + Duration::nanoseconds(ns);

    let offset = FixedOffset::east((dto.offset as i32) * 60);
