pub fn reverse_words(words: Vec<&str>) -> Vec<String> {
    let mut reversed_words: Vec<String> = Vec::new(); // initialize an empty vector to hold the reversed words

    for word in &words {
        // iterate over words, word is the actual word

        let mut reversed_word = String::new(); // create a new String for the reversed word

        // iterate over the word in reverse and push each character to reversed_word
        for i in (0..word.len()).rev() {
