pub fn assertive_median<T>(l: &Vec<T>, cmp_func: impl Fn(&T, &T) -> std::cmp::Ordering) -> Option<T> 
where 
    T: Copy + FromPrimitive + Ord, 
{
    let length = l.len(); 
    // If the vector is empty, we return None
    if length == 0 {
        return None;
    }

    // Create a clone of our list and sort it by applying our comparator function
    let mut sorted_vec = l.clone();
    sorted_vec.sort_by(cmp_func);

    // If the vector's length is even, we find the two middle numbers, add them and divide by 2
    // Else, return the middle number
    if length % 2 == 0 {
        let mid1 = sorted_vec[length / 2 - 1];
        let mid2 = sorted_vec[length / 2];
        Some(T::from_f64((mid1 + mid2) as f64 / 2.0).unwrap())
    } else {
        Some(sorted_vec[length / 2])
    }
}
```
