use num::Float;

pub fn accurate_largest_prime_factor_v2(n: f64) -> i32 {
    // Converting the absolute value of the input into an integer
    let mut n = n.abs() as i32; 

    // Initializing the maximum prime factor to -1
    let mut max_prime = -1;

    // Dividing n by 2 until n becomes odd
    while n % 2 == 0 {
        max_prime = 2;
        n >>= 1;  // equivalent to n /= 2
    }

    // n must be odd at this point, thus increment the counter by 2
    let sqrt_n = (n as f64).sqrt() as i32;
    for i in (3..(sqrt_n + 1)).step_by(2) {
        while n % i == 0 {
            max_prime = i;
            n /= i;
        }
    }

    // If n is a prime number and greater than two, then n itself is the maximum prime
    if n > 2 {
        max_prime = n;
    }

    max_prime
}

