fn find_highest_prime(numbers: &[i32]) -> Option<i32> {
    let mut highest_prime: Option<i32> = None;

    for &num in numbers {
        if is_prime(num) {
            highest_prime = Some(num.max(highest_prime.unwrap_or(num)));
        }
    }

    highest_prime
}

