        .split(',')
        .map(|x| x.parse::<i32>())
        .filter_map(Result::ok)
        .collect();

    if numbers.is_empty() {
        println!("The array is empty.");
        return;
    }

    match find_highest_prime(&numbers) {
        Some(highest_prime) => println!("The highest prime number is {}", highest_prime),
        None => println!("There are no prime numbers in the array."),
    }
}
